%[text] **Author: Andreas Apostolatos, PhD (aapostol@mathworks.com)**
%[text] **Date: 20.02.2023**
%%
%[text] %[text:anchor:H_107BC2D7] ## Preamble
clc;
clear;
close all;
%%
%[text] %[text:anchor:H_7DE3BCB3] ## **Problem setup**
%[text] %[text:anchor:H_04EF4019] ### Definition of the geometric parameters
%[text] %[text:anchor:M_65D66094] Thickness \[m\]
propStr.t = 10^(-2); %[control:slider:334b]{"position":[17,19]}
%[text] Width \[m\]
propStr.b = .1;
%[text] Height \[m\]
propStr.A = propStr.b*propStr.t;
%[text] X-coordinate at the left end of the beam \[m\]
X0 = 0;
%[text] Y-coordinate at the right end of the beam \[m\]
XL = 4;
%[text] %[text:anchor:H_65D1E7A7] ### Definition of the loading and material paramerters
%[text] Distributed load along the beam's length \[N/m\]
propStr.qBar = -3e4*(propStr.t)^3;
%[text] Distributed moment along the beam's length \[N\]
propStr.mBar = 0;
%[text] Young's modulus \[N/m^2\]
propStr.E = 1e7;
%[text] Poisson ratio \[dimensionless\]
propStr.nu = .3;
%[text] Moment of inertia \[m^4\]
propStr.I = propStr.b*(propStr.t^3)/12;
%[text] Shear modulus (connected to `epsilon_12 = E/(1+nu)`) \[N/m^2\]
propStr.G = propStr.E/(2*(1 + propStr.nu));
%[text] Shear correction factor \[dimensionless\]
propStr.alpha = 5/6;
%%
%[text] %[text:anchor:H_D2431383] ## Derivation of the analytical solution
%[text] Since the plate is rectangular, clamped on its one end while being subject to constant distributed vertical load its behavior is expected to resemble a beam aligned with the $X$-axis, whereas no effects are expected to take place along the $Y$-axis. The analytical solution for this problem using the shear-deformable Timoshenko beam formulation are in this case as follows
syms wEx(X) betaEx(X) Lsym qsym Gsym Aqsym Esym Isym
%[text] Set the analytical solution in terms of the vertical deflection field (Eq. (6) in the introduction):
%[text] $w(X) = \\frac{1}{\\alpha G A} \\left( \\overline{q} L X - \\frac{\\overline{q} X^2}{2} \\right) - \\frac{1}{EI} \\left( - \\frac{\\overline{q} X^4}{24} + \\frac{\\overline{q} L X^3}{6} - \\frac{\\overline{q} L^2 X^2}{4} \\right) \\qquad (8)$,
%[text] namely:
wEx(X) = (qsym*Lsym*X-qsym*X^2/2)/Gsym/(Aqsym) - ...
    (-qsym*X^4/24+qsym*Lsym*X^3/6-qsym*Lsym^2*X^2/4)/Esym/Isym;
%[text] Get the analytical solution of the rotational field by leveraging the Partial Differential Equation (PDE) of the problem and the functions of the [Symbolic Math Toolbox](https://www.mathworks.com/products/symbolic.html)™ in [MATLAB](https://www.mathworks.com/products/matlab.html)®
%[text] $\\beta(X) = \\int\_{0}^L - \\frac{1}{\\alpha G A}\\overline{q} - \\frac{\\text{d}^2 w}{\\text{d} x^2} \\: \\text{d}x \\qquad (9)$
betaEx(X) = int(-1/(propStr.alpha*propStr.G*propStr.b*propStr.t)*propStr.qBar ...
    - diff(diff(wEx, X), X));
%[text] Evaluate the expressions for the given geometric and material parameters
wEx(X) = subs(wEx,{Lsym, qsym, Gsym, Esym, Isym, Aqsym}, ...
    {XL, propStr.qBar, propStr.G, propStr.E, propStr.b*(propStr.t^3)/12, ...
    propStr.alpha*propStr.b*propStr.t});
betaEx(X) = subs(betaEx,{Lsym, qsym, Gsym, Esym, Isym, Aqsym}, ...
    {XL, propStr.qBar, propStr.G, propStr.E, propStr.b*(propStr.t^3)/12, ...
    propStr.alpha*propStr.b*propStr.t});
%%
%[text] %[text:anchor:H_8A770170] ## **Basis functions**
%[text] %[text:anchor:H_50D2A082] ### Linear shape functions
%[text] $\\begin{array}{l}\nN\_1 \\left(\\xi \\right)=\\frac{1-\\xi }{2},\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(10\\ldotp 1\\right)\\\\\nN\_2 \\left(\\xi \\right)=\\frac{1+\\xi }{2}\\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(10\\ldotp 2\\right)\n\\end{array}${"editStyle":"visual"}
%[text] %[text:anchor:H_720008AE] #### Definition of the one-dimensional linear Lagrange polynomials
syms l1L1(X, X1, X2) l2L1(X, X1, X2)
l1L1(X, X1, X2) = (X - X2)/(X1 - X2);
l2L1(X, X1, X2) = (X - X1)/(X2 - X1);
%[text] %[text:anchor:H_C8EED2CE] #### Definition and visualization of the one-dimensional linear (hat) basis functions
syms xi N1L1(xi) N2L1(xi) NL1(xi)
N1L1(xi) = l1L1(xi, -1, +1);
N2L1(xi) = l2L1(xi, -1, +1);
NL1(xi) = [N1L1(xi) N2L1(xi)];
fplot(NL1, [-1 1], LineWidth=4); %[output:02d12517]
xlabel("\xi"); %[output:02d12517]
ylabel("N_i^{L_1}(\xi)") %[output:02d12517]
legend("N_1^{L_1}", "N_2^{L_2}", Location="best"); %[output:02d12517]
title("Linear (hat) shape functions") %[output:02d12517]
%[text] %[text:anchor:H_59C5CE4C] ### Quadratic shape functions
%[text] $\\begin{array}{l}\nN\_1 \\left(\\xi \\right)=\\frac{\\xi \\;\\left(\\xi -1\\right)}{2},\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(11\\ldotp 1\\right)\\\\\nN\_2 \\left(\\xi \\right)=\\frac{\\xi \\;\\left(\\xi +1\\right)}{2}\\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(11\\ldotp 2\\right)\\\\\nN\_3 \\left(\\xi \\right)=-\\left(\\xi -1\\right)\\;\\;\\left(\\xi +1\\right),\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(11\\ldotp 3\\right)\n\\end{array}${"editStyle":"visual"}
%[text] %[text:anchor:H_2A8C6737] #### Definition of the one-dimensional linear Lagrange polynomials
syms l1L2(X, X1, X2, X3) l2L2(X, X1, X2, X3) l3L2(X, X1, X2, X3)
l1L2(X, X1, X2, X3) = (X - X2)/(X1 - X2)*(X - X3)/(X1 - X3);
l2L2(X, X1, X2, X3) = (X - X1)/(X2 - X1)*(X - X3)/(X2 - X3);
l3L2(X, X1, X2, X3) = (X - X1)/(X3 - X1)*(X - X2)/(X3 - X2);
%[text] %[text:anchor:H_0AC24049] #### Definition and visualization of the one-dimensional quadratic basis functions
syms N1L2(xi) N2L2(xi) N3L2(xi) NL2(xi)
N1L2(xi) = l1L2(xi, -1, 0, +1);
N2L2(xi) = l2L2(xi, -1, 0, +1);
N3L2(xi) = l3L2(xi, -1, 0, +1);
NL2(xi) = [N1L2(xi) N3L2(xi) N2L2(xi)];
fplot(NL2, [-1 1], LineWidth=4); %[output:88bd544b]
xlabel("\xi"); %[output:88bd544b]
ylabel("N_i^{L_2}(\xi)") %[output:88bd544b]
legend("N_1^{L_2}", "N_2^{L_2}", "N_3^{L_2}", Location="best"); %[output:88bd544b]
title("Quadratic basis functions") %[output:88bd544b]
%%
%[text] %[text:anchor:H_0DF3A077] ## **Basis functions derivatives**
%[text] %[text:anchor:H_C3A73EAD] ### Derivation of the parametric derivatives of the linear (hat) shape functions
%[text] $\\begin{array}{l}\n\\frac{{\\partial N}\_1 \\left(\\xi \\right)}{\\partial \\xi }=-\\frac{1}{2},\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(12\\ldotp 1\\right)\\\\\n\\frac{{\\partial N}\_2 \\left(\\xi \\right)}{\\partial \\xi }=\\frac{1}{2}\\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(12\\ldotp 2\\right)\n\\end{array}${"editStyle":"visual"}
fplot(diff(NL1, xi), [-1 1]); %[output:3056c447]
xlabel("\xi"); %[output:3056c447]
ylabel("$\frac{d N_i^{L_1}(\xi)}{d \xi}$", Interpreter="latex"); %[output:3056c447]
legend("$\partial N_1^{L_1} / \partial \xi$", ... %[output:3056c447]
    "$\partial N_2^{L_1} / \partial \xi$", Interpreter="latex"); %[output:3056c447]
title("Derivatives of the linear (hat) shape functions") %[output:3056c447]
%[text] %[text:anchor:H_4C742864] ### Derivation of the parametric derivatives of the quadratic basis functions
%[text] $\\begin{array}{l}\n\\frac{{\\partial N}\_1 \\left(\\xi \\right)}{\\partial \\xi }=\\xi -\\frac{1}{2},\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(13\\ldotp 1\\right)\\\\\n\\frac{{\\partial N}\_2 \\left(\\xi \\right)}{\\partial \\xi }=-2\\;\\xi \\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(13\\ldotp 2\\right)\\\\\n\\frac{{\\partial N}\_3 \\left(\\xi \\right)}{\\partial \\xi }=\\xi +\\frac{1}{2}\\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(13\\ldotp 3\\right)\n\\end{array}${"editStyle":"visual"}
fplot(diff(NL2, xi), [-1 1]); %[output:97d5b9dd]
xlabel("\xi"); %[output:97d5b9dd]
ylabel("$\frac{d N_i^{L_2}(\xi)}{d \xi}$", Interpreter="latex"); %[output:97d5b9dd]
legend("$\partial N_1^{L_2} / \partial \xi$", ... %[output:97d5b9dd]
    "$\partial N_3^{L_2} / \partial \xi$", "$\partial N_2^{L_2} / \partial \xi$", ... %[output:97d5b9dd]
    Interpreter="latex"); %[output:97d5b9dd]
title("Derivatives of the quadratic basis functions") %[output:97d5b9dd]
%%
%[text] %[text:anchor:H_BAF5AFE9] ## Discretization
%[text] Both the vertical deflection $w$ and cross-sectional rotation $\\beta$ fields are discretized using the same basis (shape) functions, namely:
%[text] $\\begin{array}{l}\nw\\left(x\\right)\\approx \\sum\_{i=1:N} N\_i \\;w\_i ,\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(14\\ldotp 1\\right)\\\\\n\\beta \\left(x\\right)\\approx \\sum\_{i=1:N} N\_i \\;\\beta\_i \\;\\ldotp \\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\;\\left(14\\ldotp 2\\right)\n\\end{array}${"editStyle":"visual"}
%[text] Here $N$ indicates the total number of nodes in the mesh. Moreover, a Buvnov-Galerkin discretization is used, meaning that both the test and the unknown fields are discretized using the same basis (shape) functions.
%%
%[text] %[text:anchor:H_A6B3119B] ### Generation and visualization of an one-dimensional mesh using linear two-noded elements
%[text] %[text:anchor:H_A5EB2A3E] #### Mesh generation
numEl = 20;
mshL1 = generateLinearMeshOnLine(X0, XL, numEl);
isLinearMeshNonuniform = false; %[control:checkbox:024a]{"position":[26,31]}
if isLinearMeshNonuniform
    dX = mshL1.nodes(2, 1) - mshL1.nodes(1, 1);
    for ii = 2:numel(mshL1.nodes(:, 1)) - 1
        mshL1.nodes(ii, 1) = mshL1.nodes(ii, 1) + (2.*rand(1, 1) -1)/(4*dX);
    end
end
%[text] %[text:anchor:H_44DD5C6C] #### Dirichlet boundary conditions
numDOFsL1 = 2*numel(mshL1.nodes(:, 1));
freeDOFsL1 = 1:numDOFsL1;
homDOFsL1 = 1:2;
[~, idxL1] = ismember(homDOFsL1, freeDOFsL1);
freeDOFsL1(idxL1) = [];
%[text] %[text:anchor:H_9F06C917] #### Mesh plot
plotMesh1d(mshL1); %[output:058be0ad]
title("Finite Element discretization of the beam using " + ... %[output:group:84ee95fa] %[output:058be0ad]
    "two-noded linear elements") %[output:group:84ee95fa] %[output:058be0ad]
%[text] ![](text:image:1d76) **Try**
%[text] Change the flag `isLinearMeshNonuniform` to true and observe the mesh. 
%[text] ![](text:image:0de3) **Reflect**
%[text] What can you say about the determinant of the Jacobian for the elements that are inverted?
%%
%[text] %[text:anchor:H_44A658B1] ### Generation and visualization of an one-dimensional mesh using quadratic three-noded elements
%[text] %[text:anchor:H_CE948878] #### Mesh generation
mshL2 = generateQuadraticMeshOnLine(mshL1);
isQuadraticMeshNonuniform = false; %[control:checkbox:26d7]{"position":[29,34]}
if isQuadraticMeshNonuniform
    for ii = numel(mshL1.nodes(:, 1)) + 1:numel(mshL2.nodes(:, 1))
        mshL2.nodes(ii, 1) = mshL2.nodes(ii, 1) + (2.*rand(1, 1) -1)/5;
    end
end
%[text] %[text:anchor:H_7170963E] #### Dirichlet boundary conditions
numDOFsL2 = 2*numel(mshL2.nodes(:, 1));
freeDOFsL2 = 1:numDOFsL2;
homDOFsL2 = 1:2;
[~, idxL2] = ismember(homDOFsL2, freeDOFsL2);
freeDOFsL2(idxL2) = [];
%[text] %[text:anchor:H_CF126528] #### Mesh plot
plotMesh1d(mshL2); %[output:8e1a9694]
title("Finite Element discretization of the beam using " + ... %[output:group:96d27c61] %[output:8e1a9694]
    "three-noded quadratic elements") %[output:group:96d27c61] %[output:8e1a9694]
