%[text] %[text:anchor:H_CA13D995] ## Master stiffness matrix and load vector for the two-noded linear mesh
%[text] %[text:anchor:H_B0A5160B] ### Initialization of the master stiffness matrix and master load vector
KL1 = zeros(numDOFsL1);
FL1 = zeros(numDOFsL1, 1);
%[text] %[text:anchor:H_37039879] ### Loop over all the elements in the mesh and assemble to the master stiffness matrix and master load vector
for ii = 1:numEl
%[text] %[text:anchor:H_65F99FC4] #### Nodal indices and nodal coordinates
    id = mshL1.elements(ii, :);
    nodesEl = mshL1.nodes(id);
%[text] %[text:anchor:H_A828DC82] #### Element stiffness matrix
    [KEl, FEl] = computeElementStiffnessMatrixandForceVectorTimoshenkoBeam ...
        (NL1, nodesEl, propStr);
%[text] %[text:anchor:H_ABEBB88D] #### Element Freedom Table (EFT)
    EFT = vertcat(2*id - 1, 2*id);
    EFT = EFT(:);
%[text] %[text:anchor:H_4968860C] #### Assembly to the master stiffness matrix and load vector
    KL1(EFT, EFT) = KL1(EFT, EFT) + KEl;
    FL1(EFT) = FL1(EFT) + FEl;
%[text] 
end
%[text] %[text:anchor:H_940C4B6B] ### Sparsity of the master global stiffness matrix
spy(KL1) %[output:56bbb384]
