%[text] %[text:anchor:H_DBADC31D] ## Master stiffness matrix and load vector for the three-noded quadratic mesh
%[text] %[text:anchor:H_400AB350] ### Initialization of the master stiffness matrix and master load vector
KL2 = zeros(numDOFsL2);
FL2 = zeros(numDOFsL2, 1);
%[text] %[text:anchor:H_56573F50] ### Loop over all the elements in the mesh and assemble to the master stiffness matrix and master load vector
for ii = 1:numEl
%[text] %[text:anchor:H_597D5D33] #### Nodal indices and nodal coordinates
    id = mshL2.elements(ii, :);
    nodesEl = mshL2.nodes(id);
%[text] %[text:anchor:H_9EF225E4] #### Element stiffness matrix
    [KEl, FEl] = computeElementStiffnessMatrixandForceVectorTimoshenkoBeam ...
        (NL2, nodesEl, propStr);
%[text] %[text:anchor:H_B3014E9E] #### Element Freedom Table (EFT)
    EFT = vertcat(2*id - 1, 2*id);
    EFT = EFT(:);
%[text] %[text:anchor:H_348F6CEB] #### Assembly to the master stiffness matrix and load vector
    KL2(EFT, EFT) = KL2(EFT, EFT) + KEl;
    FL2(EFT) = FL2(EFT) + FEl;
%[text] 
end
%[text] %[text:anchor:H_DCCD2951] ### Sparsity of the master global stiffness matrix
spy(KL2) %[output:269991ad]
