%%
%[text] %[text:anchor:H_ED60E4F1] ## References
%[text] [\[1\] Hughes, Thomas JR. *The finite element method: linear static and dynamic finite element analysis*. Courier Corporation, 2012.](https://doi.org/10.1111/j.1467-8667.1989.tb00025.x)
%[text] [](https://doi.org/10.1007/978-3-030-76035-9)[\[2\] Öchsner, Andreas. *Classical beam theories of structural mechanics*. Cham: Springer, 2021.](https://doi.org/10.1007/978-3-030-76035-9)
%%
%[text] %[text:anchor:H_696BABBA] ## **Helper functions**
%[text] %[text:anchor:H_CF308BE4] ### **Element Stiffness Matrix and body force vector**
function [Ke, Fe] = computeElementStiffnessMatrixandForceVectorTimoshenkoBeam ...
    (N, nodesEl, propStr)
%[text] **Function description**
%[text] Computation of the element stiffness matrix for an element based on the 1D Timoshenko-beam theory with two degrees of freedom per node $\\left(w,\\beta \\right)${"editStyle":"visual"}, one of the vertical deflection and another one for the shear rotation:
%[text] $\\begin{array}{l}\nK\_{\\textrm{ij}}^w =\\int\_0^l \\alpha \\textrm{GA}\\left(\\frac{dN\_i^w }{\\textrm{dX}}+N\_i^{\\beta } \\right)\\left(\\frac{dN\_j^w }{\\textrm{dX}}+N\_j^{\\beta } \\right)\\textrm{dx}\\;,\\\\\nK\_{\\textrm{ij}}^{\\beta } =\\int\_0^l \\textrm{EI}\\left(\\frac{dN\_i^{\\beta } }{\\textrm{dx}}\\right)\\frac{dN\_j^{\\beta } }{\\textrm{dx}}\\;\\;\\textrm{dx}\\;\\ldotp \n\\end{array}${"editStyle":"visual"}
%[text]  **Input :**
%[text]  `N` : Vector containing the symbolic expression for the basis functions
%[text]  `nodesEl` : Nodal coordinates of the finite element arranged in a column-vector
%[text]  `propStr` : Structure containing the following fields,
%[text]  `.A` : Cross sectional area of the beam
%[text]  `.q` : Distributed load on the beam
%[text]  `.m` : Distributed moment on the beam
%[text]  `.E` : Young's modulus
%[text]  `.nu` : Poisson's ratio
%[text]  `.I` : Moment of inertia
%[text]  `.G` : Shear modulus
%[text]  `.alpha` : Shear correction factor
%[text]  **Output :**
%[text]  `Ke` : Element stiffness matrix of a Timoshenko beam
%[text]  `Fe` : Element force vector of the Timoshenko beam
%[text] **Function implementation**
%[text] Set-up the geometric map $x(\\xi) = \\sum\_{i=1}^n N\_i(\\xi) x\_i$:
syms xi
numNodesEl = numel(N(xi));
xel = sym('xel', [numNodesEl 1]);
x = N*xel;
%[text] Get the polynomial order of the element
pEl = numNodesEl - 1;
%[text] Get the number of DOFs per element
numDOFsEl = 2*numNodesEl;
%[text] Set-up the Jacobian $J(\\xi) = \\frac{\\text{d} x(\\xi)}{\\text{d} \\xi} = \\sum\_{i = 1}^n \\frac{\\text{d} N\_i(\\xi)}{\\text{d} \\xi}x\_i$:
J = jacobian(x, xi);
%[text] Transform the derivatives of the basis functions from the parametric to the physical space
%[text] $\\frac{\\text{d} N\_i (\\xi)}{\\text{d} x} = \\frac{\\text{d} N\_i (\\xi)}{\\text{d} \\xi} \\frac{\\text{d} \\xi}{\\text{d} x} = \\frac{\\text{d} N\_i (\\xi)}{\\text{d} \\xi} J^{-1}$ 
syms dN(xi)
dN(xi) = J\diff(N, xi);
%[text] Computation of the material matrix
syms alpha_scf G A E I
C = [alpha_scf*G*A 0
     0             E*I];
%[text] Symbolic formulation of the basis function matrix
Nmtx = sym(zeros(2, numDOFsEl));
for ii = 1:numNodesEl
    filtermtx = zeros(numNodesEl, 1);
    filtermtx(ii) = 1;
    Nmtx(1, 2*ii - 1) = N*filtermtx;
    Nmtx(2, 2*ii) = N*filtermtx;
end
%[text] Symbolic formulation of the B-Operator matrix
Bmtx = sym(zeros(2, numDOFsEl));
for ii = 1:numNodesEl
    filtermtx = zeros(numNodesEl, 1);
    filtermtx(ii) = 1;
    Bmtx(1, 2*ii - 1) = dN*filtermtx;
    Bmtx(1, 2*ii) = N*filtermtx;
    Bmtx(2, 2*ii) = dN*filtermtx;
end
%[text] Set up element stiffness matrix and load vector integrands
syms qBar mBar Ke_integrand(xi) Fe_integrand(xi)
Ke_integrand(xi) = transpose(Bmtx)*C*Bmtx;
Fe_integrand(xi) = transpose(Nmtx)*[qBar; mBar];
%[text] Choose method for computing the element stiffness matrix
integrationMethod = 2; %[control:dropdown:102c]{"position":[21,22]}
%[text] Compute the symbolic expression of the element stiffness matrix and load vector based on the selected method
switch integrationMethod
%[text] *1.) Method 1: Perform the variable substitution* $\\xi =\\xi \\left(X\\right)${"editStyle":"visual"} which is the inverse of map $X=X\\left(\\xi \\right)${"editStyle":"visual"}:
    case 0
%[text] $B\\left(\\xi \\right)=B\\left(\\xi \\left(X\\right)\\right)=\\bar{B} \\left(X\\right),${"editStyle":"visual"}
%[text] $\\int\_{X\_1 }^{X\_2 } B^T \\left(\\xi \\right)\\textrm{CB}\\left(\\xi \\right)\\;\\textrm{dx}=\\int\_{X\_1 }^{X\_2 } {\\bar{B} }^T \\left(x\\right)C\\bar{B} \\left(x\\right)\\;\\textrm{dx}${"editStyle":"visual"}
%[text] $\\int\_{X\_1 }^{X\_2 } N^T \\left(\\xi \\right)p\\left(\\xi \\right)\\;\\textrm{dx}=\\int\_{X\_1 }^{X\_2 } {\\bar{N} }^T \\left(x\\right)\\bar{p} \\left(x\\right)\\;\\textrm{dx}${"editStyle":"visual"}
        syms X
        Xxi = solve(X == x(xi), xi);
        Ke_integrand_bar = subs(Ke_integrand, xi, Xxi);
        Fe_integrand_bar = subs(Fe_integrand, xi, Xxi);
        Ke_int = int(Ke_integrand_bar, X, nodesEl(1), nodesEl(2));
        Fe_int = int(Fe_integrand_bar, X, nodesEl(1), nodesEl(2));
%[text] *2.) Method 2: Transform the element stiffness matrix in the element's parent space \[-1 , 1\]:*
    case 1
%[text] $\\int\_{X\_1 }^{X\_2 } B^T \\left(\\xi \\right)\\textrm{CB}\\left(\\xi \\right)\\;\\textrm{dX}=\\int\_{-1}^{+1} B^T \\left(\\xi \\right)\\textrm{CB}\\left(\\xi \\right)\\;\\det \\left(J\\left(\\xi \\right)\\right)\\;d\\xi${"editStyle":"visual"}
%[text] $\\int\_{X\_1 }^{X\_2 } N\\left(\\xi \\right)p\\left(\\xi \\right)\\;\\textrm{dX}=\\int\_{-1}^{+1} N\\left(\\xi \\right)p\\left(\\xi \\right)\\;\\det \\left(J\\left(\\xi \\right)\\right)\\;d\\xi${"editStyle":"visual"}
%[text] Symbolic computation of the element stiffness matrix
        Ke_int = int(Ke_integrand*det(J), xi, -1, 1);
        Fe_int = int(Fe_integrand*det(J), xi, -1, 1);
%[text] *3.) Method 3: Transform the element stiffness matrix in the element's parent space \[-1 , 1\] and perform Gaussian integration*
    case 2
%[text] $\\int\_{X\_1 }^{X\_2 } B^T \\left(\\xi \\right)\\textrm{CB}\\left(\\xi \\right)\\;\\textrm{dx}=\\int\_{-1}^{+1} B^T \\left(\\xi \\right)\\textrm{CB}\\left(\\xi \\right)\\;\\det \\left(J\\left(\\xi \\right)\\right)\\;d\\xi =\\sum\_{i=1}^2 B^T \\left(\\xi\_i \\right)\\textrm{CB}\\left(\\xi\_i \\right)\\;\\det \\left(J\\left(\\xi\_i \\right)\\right)w\_i${"editStyle":"visual"}
%[text] $\\int\_{X\_1 }^{X\_2 } N\\left(\\xi \\right)p\\left(\\xi \\right)\\;\\textrm{dx}=\\int\_{-1}^{+1} N\\left(\\xi \\right)p\\left(\\xi \\right)\\;\\det \\left(J\\left(\\xi \\right)\\right)\\;d\\xi =\\sum\_{i=1}^2 N\\left(\\xi\_i \\right)p\\left(\\xi\_i \\right)\\;\\det \\left(J\\left(\\xi\_i \\right)\\right)w\_i${"editStyle":"visual"}
%[text] Symbolic computation of the element stiffness matrix
        numGP = pEl + 1;
        [xiGP, GW_xi] = getGaussPointsAndWeightsOverUnitDomain(numGP);
        Ke_int = sym(zeros(numDOFsEl));
        Fe_int = sym(zeros(numDOFsEl, 1));
        for ii = 1:height(GW_xi)
            Ke_int = Ke_int + Ke_integrand(xiGP(ii))*det(J(xiGP(ii)))*GW_xi(ii);
            Fe_int = Fe_int + Fe_integrand(xiGP(ii))*det(J(xiGP(ii)))*GW_xi(ii);
        end
%[text] *4.) Method 4: Transform the element stiffness matrix in the element's parent space \[-1 , 1\] and perform reduced integration*
    case 3
%[text] $\\int\_{X\_1 }^{X\_2 } B^T \\left(\\xi \\right)\\textrm{CB}\\left(\\xi \\right)\\;\\textrm{dx}=\\int\_{-1}^{+1} B^T \\left(\\xi \\right)\\textrm{CB}\\left(\\xi \\right)\\;\\det \\left(J\\left(\\xi \\right)\\right)\\;d\\xi =\\sum\_{i=1}^1 B\_{\\textrm{shear}}^T \\left(\\xi\_i \\right)C\_{\\textrm{shear}} B\_{\\textrm{shear}} \\left(\\xi\_i \\right)\\;\\det \\left(J\\left(\\xi\_i \\right)\\right)w\_i +\\sum\_{i=1}^2 B\_{\\textrm{bending}}^T \\left(\\xi\_i \\right)C\_{\\textrm{bending}} B\_{\\textrm{bending}} \\left(\\xi\_i \\right)\\;\\det \\left(J\\left(\\xi\_i \\right)\\right)w\_i${"editStyle":"visual"}
%[text] $\\int\_{X\_1 }^{X\_2 } N\\left(\\xi \\right)p\\left(\\xi \\right)\\;\\textrm{dx}=\\int\_{-1}^{+1} N\\left(\\xi \\right)p\\left(\\xi \\right)\\;\\det \\left(J\\left(\\xi \\right)\\right)\\;d\\xi =\\sum\_{i=1}^n N\\left(\\xi\_i \\right)p\\left(\\xi\_i \\right)\\;\\det \\left(J\\left(\\xi\_i \\right)\\right)w\_i${"editStyle":"visual"}
%[text] Symbolic computation of the element stiffness matrix using Gaussian integration:
        syms Ke_shear_integrand(xi) Ke_bending_integrand(xi) Fe_integrand(xi)
        Ke_shear_integrand(xi) = [[1 0]*Bmtx
                                  sym(zeros(1, numDOFsEl))]'*C*[[1 0]*Bmtx
                                  sym(zeros(1, numDOFsEl))];
        Ke_bending_integrand(xi) = [sym(zeros(1, numDOFsEl))
                                    [0 1]*Bmtx]'*C*[sym(zeros(1, numDOFsEl))
                                    [0 1]*Bmtx];
        Fe_integrand(xi) = transpose(Nmtx)*[qBar; mBar];
%[text] Compute the shear part of the stiffness matrix using reduced integration (number of required Gauss points for integration without rigid body modes minus one):
        numGP = pEl;
        [xiGP, GW_xi] = getGaussPointsAndWeightsOverUnitDomain(numGP);
        Ke_shear_int = sym(zeros(numDOFsEl));
        for ii = 1:height(GW_xi)
            Ke_shear_int = Ke_shear_int + ...
                Ke_shear_integrand(xiGP(ii))*det(J(xiGP(ii)))*GW_xi(ii);
        end
%[text] Compute the bending part of the stiffness matrix using full integration (number of required Gauss points for integration without rigid body modes):
        numGP = pEl + 1;
        [xiGP, GW_xi] = getGaussPointsAndWeightsOverUnitDomain(numGP);
        Ke_bending_int = sym(zeros(numDOFsEl));
        Fe_int = sym(zeros(numDOFsEl, 1));
        for ii = 1:height(GW_xi)
            Ke_bending_int = Ke_bending_int + ...
                Ke_bending_integrand(xiGP(ii))*det(J(xiGP(ii)))*GW_xi(ii);
            Fe_int = Fe_int + ...
                Fe_integrand(xiGP(ii))*det(J(xiGP(ii)))*GW_xi(ii);
        end
%[text] Add the shear and the bending parts of the stiffness matrix:
        Ke_int = Ke_shear_int + Ke_bending_int;
%[text] Assert an error in case neither of cases 0, 1, 2 or 3 is chosen:
    otherwise
        error("Variable 'method' should take the values 0, 1, 2 or 3 but it has instead the value %d\n", integrationMethod);
end
%[text] Numerical evaluation of the element stiffness matrix and load vector
Ke = subs(Ke_int, [alpha_scf, G, E, A, I, transpose(xel)], ...
    [propStr.alpha, propStr.G, propStr.E, propStr.A, ...
    propStr.I, transpose(nodesEl)]);
Fe = subs(Fe_int, [qBar, mBar, transpose(xel)], ...
    [propStr.qBar, propStr.mBar, transpose(nodesEl)]);
%[text] Computation of the analytical formula for the stiffness matrix
isDebug = false; %[control:checkbox:0bee]{"position":[11,16]}
if isDebug
    Ke_analytical = [propStr.alpha*propStr.G*propStr.A/(x2 - x1)  -propStr.alpha*propStr.G*propStr.A/2                                           -propStr.alpha*propStr.G*propStr.A/(x2 - x1) -propStr.alpha*propStr.G*propStr.A/2
                     -propStr.alpha*propStr.G*propStr.A/2         -propStr.alpha*propStr.G*propStr.A*(x2 - x1)/3 + propStr.E*propStr.I/(x2 - x1) propStr.alpha*propStr.G*propStr.A/2          propStr.alpha*propStr.G*propStr.A*(x2 - x1)/6 - propStr.E*propStr.I/(x2 - x1)
                     -propStr.alpha*propStr.G*propStr.A/(x2 - x1) propStr.alpha*propStr.G*propStr.A/2                                            propStr.alpha*propStr.G*propStr.A/(x2 - x1)  propStr.alpha*propStr.G*propStr.A/2
